# New hypothesis: Ray casting from each 5 - horizontal and vertical rays extend until they hit another 5
def solve_ray_cast(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    # For each 5, cast horizontal and vertical rays
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5:
                # Horizontal ray left
                for kc in range(c - 1, -1, -1):
                    if result[r][kc] == 5:
                        break
                    if result[r][kc] == 0:
                        result[r][kc] = 2

                # Horizontal ray right
                for kc in range(c + 1, m):
                    if result[r][kc] == 5:
                        break
                    if result[r][kc] == 0:
                        result[r][kc] = 2

                # Vertical ray up
                for kr in range(r - 1, -1, -1):
                    if result[kr][c] == 5:
                        break
                    if result[kr][c] == 0:
                        result[kr][c] = 2

                # Vertical ray down
                for kr in range(r + 1, n):
                    if result[kr][c] == 5:
                        break
                    if result[kr][c] == 0:
                        result[kr][c] = 2

    return result

