# New hypothesis: Fill cell if there's a 5 on BOTH left and right (or above and below)
def solve_sandwich(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                # Check horizontal sandwich
                has_5_left = any(grid[r][kc] == 5 for kc in range(c))
                has_5_right = any(grid[r][kc] == 5 for kc in range(c+1, m))

                if has_5_left and has_5_right:
                    result[r][c] = 2
                else:
                    # Check vertical sandwich
                    has_5_above = any(grid[kr][c] == 5 for kr in range(r))
                    has_5_below = any(grid[kr][c] == 5 for kr in range(r+1, n))

                    if has_5_above and has_5_below:
                        result[r][c] = 2

    return result

