# Test hypothesis: Fill rows above/below based on bbox edges

def solve_bbox_projection(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    # Find bounding box of all 5s
    min_r, max_r = n, -1
    min_c, max_c = m, -1

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if min_r == n:  # No 5s found
        return result

    # For rows ABOVE the bbox (r < min_r)
    for r in range(min_r):
        # Fill from left_edge to right_edge of bbox
        for c in range(min_c, max_c):
            if result[r][c] == 0:
                result[r][c] = 2

    # For rows BELOW the bbox (r > max_r)
    for r in range(max_r + 1, n):
        for c in range(min_c, max_c):
            if result[r][c] == 0:
                result[r][c] = 2

    # Fill interior horizontally for each row within bbox
    for r in range(min_r, max_r + 1):
        positions = [(c,v) for c,v in enumerate(result[r]) if v == 5]
        if len(positions) >= 2:
            left, right = positions[0][0], positions[-1][0]
            for c in range(left + 1, right):
                if result[r][c] == 0:
                    result[r][c] = 2

    return result

