def solve_cross_fill(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    # Horizontal fill per row
    for r in range(n):
        # Find all columns with 5s in this row
        c_5s = [c for c, v in enumerate(result[r]) if v == 5]
        if len(c_5s) >= 2:
            leftmost, rightmost = min(c_5s), max(c_5s)
            for c in range(leftmost + 1, rightmost):
                if result[r][c] == 0:
                    result[r][c] = 2

    # Vertical fill per column  
    for c in range(m):
        # Find all rows with 5s in this column
        r_5s = [r for r in range(n) if grid[r][c] == 5]
        if len(r_5s) >= 2:
            topmost, bottommost = min(r_5s), max(r_5s)
            for r in range(topmost + 1, bottommost):
                if result[r][c] == 0:
                    result[r][c] = 2

    return result

