# What if: For each column containing 5s, extend horizontally FROM each 5 until hitting another 5?
def solve_from_each_5_horizontal(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5:
                # Look left
                kc = c - 1
                while kc >= 0 and result[r][kc] != 5:
                    if result[r][kc] == 0:
                        result[r][kc] = 2
                    else:
                        break  # Hit non-zero that's not 5
                    kc -= 1

                # Look right
                kc = c + 1
                while kc < m and result[r][kc] != 5:
                    if result[r][kc] == 0:
                        result[r][kc] = 2
                    else:
                        break
                    kc += 1

    return result

