def solve_final(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    # Find connected components (boxes) of 5s
    visited = [[False]*m for _ in range(n)]
    boxes = []

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5 and not visited[r][c]:
                component = set()
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    component.add((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 5 and not visited[nr][nc]:
                            stack.append((nr, nc))
                boxes.append(component)

    print(f"Found {len(boxes)} boxes")
    for i, box in enumerate(boxes):
        min_r, max_r = min(r for r,c in box), max(r for r,c in box)
        min_c, max_c = min(c for r,c in box), max(c for r,c in box)
        print(f"Box {i}: bbox rows {min_r}-{max_r}, cols {min_c}-{max_c}")

    # Horizontal fill per row within bbox
    for r in range(n):
        positions = [c for c,v in enumerate(result[r]) if v == 5]
        if len(positions) >= 2:
            for c in range(positions[0] + 1, positions[-1]):
                if result[r][c] == 0:
                    result[r][c] = 2

    return result

