# Handle MULTIPLE boxes - apply same rule to each bbox
def solve_multi_box(grid):
    result = [row[:] for row in grid]
    n = len(grid)
    m = len(grid[0])

    # Find all 5s
    five_pos = [(r,c) for r in range(n) for c in range(m) if grid[r][c] == 5]
    if not five_pos:
        return result

    # Horizontal interior fill per row
    for r in range(n):
        positions = [c for c,v in enumerate(result[r]) if v == 5]
        if len(positions) >= 2:
            for c in range(positions[0] + 1, positions[-1]):
                if result[r][c] == 0:
                    result[r][c] = 2

    # Also do vertical fills for complete interior
    for c in range(m):
        positions = [r for r in range(n) if grid[r][c] == 5]
        if len(positions) >= 2:
            for r in range(positions[0] + 1, positions[-1]):
                if result[r][c] == 0:
                    result[r][c] = 2

    # For EACH connected component (box), fill adjacent rows above/below
    visited = [[False]*m for _ in range(n)]
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5 and not visited[r][c]:
                # BFS to find component
                component = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    component.append((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 5 and not visited[nr][nc]:
                            stack.append((nr, nc))

                # Bounding box of this component
                min_r, max_r = min(r for r,c in component), max(r for r,c in component)
                min_c, max_c = min(c for r,c in component), max(c for r,c in component)

                # Fill row above bbox (if exists)
                if min_r > 0:
                    for c in range(min_c, max_c):  # Between min_c and max_c
                        if result[min_r - 1][c] == 0:
                            result[min_r - 1][c] = 2

                # Fill row below bbox (if exists)
                if max_r < n - 1:
                    for c in range(min_c, max_c):
                        if result[max_r + 1][c] == 0:
                            result[max_r + 1][c] = 2

    return result

