    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5 and not visited[r][c]:
                component = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    component.append((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 5 and not visited[nr][nc]:
                            stack.append((nr, nc))

                min_r, max_r = min(r for r,c in component), max(r for r,c in component)
                min_c, max_c = min(c for r,c in component), max(c for r,c in component)
                box_bboxes.append((min_r, max_r, min_c, max_c))

    print(f"Boxes: {box_bboxes}")

    # Horizontal fill per row (between outermost 5s)
    for r in range(n):
        positions = [c for c,v in enumerate(result[r]) if v == 5]
        if len(positions) >= 2:
            for c in range(positions[0] + 1, positions[-1]):
                if result[r][c] == 0:
                    result[r][c] = 2

    # For each bbox, fill adjacent rows above
    for min_r, max_r, min_c, max_c in box_bboxes:
        if min_r > 0:
            for c in range(min_c, max_c):  # Between left and right edges
                if result[min_r - 1][c] == 0:
                    result[min_r - 1][c] = 2

        if max_r < n - 1:
            for c in range(min_c, max_c):
                if result[max_r + 1][c] == 0:
                    result[max_r + 1][c] = 2

    return result

